  'pet.verPlan': T('Ver el plan', 'See the plan', 'Plan ansehen', 'Voir le plan', 'Vedi il piano'),
  'pet.reintentarGuardar': T('Volver a guardar', 'Save again', 'Erneut speichern', 'Enregistrer à nouveau', 'Salva di nuovo'),
