  'pet.adaptarBorrador': T('Adapta mi lección «{titulo}» para ', 'Adapt my lesson “{titulo}” to ', 'Passe meine Lektion „{titulo}“ an: ', 'Adapte ma leçon « {titulo} » pour ', 'Adatta la mia lezione «{titulo}» per '),
  'pet.descargarLeccion': T('Descargar', 'Download', 'Herunterladen', 'Télécharger', 'Scarica'),
  'pet.quitarPreguntaDe': T('¿Quitar «{titulo}» de Mis lecciones? Se borra de este navegador con su progreso y no se puede deshacer (si quieres conservarla, descárgala antes).', 'Remove “{titulo}” from My lessons? It is deleted from this browser with its progress and cannot be undone (download it first if you want to keep it).', '„{titulo}“ aus Meine Lektionen entfernen? Sie wird mit ihrem Fortschritt aus diesem Browser gelöscht und kann nicht wiederhergestellt werden (lade sie vorher herunter, wenn du sie behalten willst).', 'Retirer « {titulo} » de Mes leçons ? Elle est supprimée de ce navigateur avec sa progression, sans retour possible (téléchargez-la d’abord pour la conserver).', 'Rimuovere «{titulo}» da Le mie lezioni? Viene eliminata da questo browser con i suoi progressi e non si può annullare (scaricala prima se vuoi conservarla).'),
  'pet.apartadasAviso': T(['{n} lección guardada no se puede abrir (dañada o de otra versión de la app). Está apartada, sin borrar: puedes descargarla para conservarla.', '{n} lecciones guardadas no se pueden abrir (dañadas o de otra versión de la app). Están apartadas, sin borrar: puedes descargarlas para conservarlas.'], ['{n} saved lesson cannot be opened (damaged or from another version of the app). It has been set aside, not deleted: you can download it to keep it.', '{n} saved lessons cannot be opened (damaged or from another version of the app). They have been set aside, not deleted: you can download them to keep them.'], ['{n} gespeicherte Lektion lässt sich nicht öffnen (beschädigt oder aus einer anderen App-Version). Sie wurde beiseitegelegt, nicht gelöscht: Du kannst sie herunterladen, um sie zu behalten.', '{n} gespeicherte Lektionen lassen sich nicht öffnen (beschädigt oder aus einer anderen App-Version). Sie wurden beiseitegelegt, nicht gelöscht: Du kannst sie herunterladen, um sie zu behalten.'], ['{n} leçon enregistrée ne peut pas être ouverte (endommagée ou d’une autre version de l’application). Elle est mise de côté, sans être supprimée : vous pouvez la télécharger pour la conserver.', '{n} leçons enregistrées ne peuvent pas être ouvertes (endommagées ou d’une autre version de l’application). Elles sont mises de côté, sans être supprimées : vous pouvez les télécharger pour les conserver.'], ['{n} lezione salvata non si può aprire (danneggiata o di un’altra versione dell’app). È stata messa da parte, senza eliminarla: puoi scaricarla per conservarla.', '{n} lezioni salvate non si possono aprire (danneggiate o di un’altra versione dell’app). Sono state messe da parte, senza eliminarle: puoi scaricarle per conservarle.']),
  'pet.descargarApartadas': T('Descargar las apartadas', 'Download the set-aside ones', 'Beiseitegelegte herunterladen', 'Télécharger celles mises de côté', 'Scarica quelle messe da parte'),
  'pet.descartarApartadas': T('Descartarlas…', 'Discard them…', 'Verwerfen …', 'Les supprimer…', 'Eliminale…'),
  'pet.descartarPregunta': T('¿Descartar las lecciones apartadas? Se borran de este navegador y no se puede deshacer.', 'Discard the set-aside lessons? They are deleted from this browser and this cannot be undone.', 'Beiseitegelegte Lektionen verwerfen? Sie werden aus diesem Browser gelöscht; das lässt sich nicht rückgängig machen.', 'Supprimer les leçons mises de côté ? Elles sont effacées de ce navigateur, sans retour possible.', 'Eliminare le lezioni messe da parte? Vengono cancellate da questo browser e non si può annullare.'),
  'pet.descartarSi': T('Sí, descartarlas', 'Yes, discard them', 'Ja, verwerfen', 'Oui, les supprimer', 'Sì, eliminale'),
  'pet.apartadasDescartadas': T('Lecciones apartadas descartadas.', 'Set-aside lessons discarded.', 'Beiseitegelegte Lektionen verworfen.', 'Leçons mises de côté supprimées.', 'Lezioni messe da parte eliminate.'),
  'pet.imp.formato': T('Ese archivo no es una exportación de Mis lecciones ni una lección de Neuri.', 'That file is not a My lessons export or a Neuri lesson.', 'Diese Datei ist weder ein Export von Meine Lektionen noch eine Neuri-Lektion.', 'Ce fichier n’est ni une exportation de Mes leçons ni une leçon de Neuri.', 'Quel file non è un’esportazione di Le mie lezioni né una lezione di Neuri.'),
  'pet.imp.noGuardado': T('No se pudo guardar nada: el navegador no tiene espacio o no deja guardar. No se ha borrado nada.', 'Nothing could be saved: the browser has no space or does not allow saving. Nothing has been deleted.', 'Es konnte nichts gespeichert werden: Der Browser hat keinen Platz oder erlaubt kein Speichern. Nichts wurde gelöscht.', 'Rien n’a pu être enregistré : le navigateur n’a plus de place ou ne permet pas d’enregistrer. Rien n’a été supprimé.', 'Non è stato possibile salvare nulla: il browser non ha spazio o non permette di salvare. Non è stato eliminato nulla.'),
  'pet.imp.nada': T('El archivo no tenía lecciones nuevas.', 'The file had no new lessons.', 'Die Datei enthielt keine neuen Lektionen.', 'Le fichier ne contenait pas de nouvelles leçons.', 'Il file non conteneva lezioni nuove.'),
  'pet.imp.añadidas': T(['{n} lección añadida', '{n} lecciones añadidas'], ['{n} lesson added', '{n} lessons added'], ['{n} Lektion hinzugefügt', '{n} Lektionen hinzugefügt'], ['{n} leçon ajoutée', '{n} leçons ajoutées'], ['{n} lezione aggiunta', '{n} lezioni aggiunte']),
  'pet.imp.copias': T(['{n} añadida como copia (ya había otra con su identificador)', '{n} añadidas como copia (ya había otras con su identificador)'], ['{n} added as a copy (another one had its identifier)', '{n} added as copies (others had their identifiers)'], ['{n} als Kopie hinzugefügt (eine andere hatte dieselbe Kennung)', '{n} als Kopien hinzugefügt (andere hatten dieselbe Kennung)'], ['{n} ajoutée comme copie (une autre avait le même identifiant)', '{n} ajoutées comme copies (d’autres avaient le même identifiant)'], ['{n} aggiunta come copia (un’altra aveva lo stesso identificativo)', '{n} aggiunte come copie (altre avevano lo stesso identificativo)']),
