  'pet.imp.invalidas': T(['{n} no es una lección válida', '{n} no son lecciones válidas'], ['{n} is not a valid lesson', '{n} are not valid lessons'], ['{n} ist keine gültige Lektion', '{n} sind keine gültigen Lektionen'], ['{n} n’est pas une leçon valide', '{n} ne sont pas des leçons valides'], ['{n} non è una lezione valida', '{n} non sono lezioni valide']),
